import React, { useRef, useState, useEffect } from "react";
import axios from "../Axios/Axios";
import "bootstrap/dist/css/bootstrap.min.css";
import {
  FaUpload,
  FaCamera,
  FaTimes,
  FaPlus,
  FaTrash,
  FaCheck,
  FaRegDotCircle,
  FaTimesCircle,
} from "react-icons/fa";

export default function AddCustomer() {
  const [image, setImage] = useState(null);
  const [file, setFile] = useState(null);
  const [showCamera, setShowCamera] = useState(false);
  const [licenses, setLicenses] = useState([]);
  const [licenseInput, setLicenseInput] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    cnic: "",
    registerDate: "",
    address: "",
  });

  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    if (showCamera) {
      async function startCamera() {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ video: true });
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.play();
          }
        } catch (err) {
          alert("Camera access denied or not available.");
          setShowCamera(false);
        }
      }
      startCamera();
    } else {
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach((track) => track.stop());
        videoRef.current.srcObject = null;
      }
    }
  }, [showCamera]);

  const captureImage = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    ctx.drawImage(video, 0, 0);

    const dataUrl = canvas.toDataURL("image/png");
    setImage(dataUrl);

    canvas.toBlob((blob) => {
      const capturedFile = new File([blob], "captured.png", { type: "image/png" });
      setFile(capturedFile);
    });

    setShowCamera(false);
  };

  const removeImage = () => {
    setImage(null);
    setFile(null);
  };

  const handleUpload = (e) => {
    const selected = e.target.files[0];
    if (selected) {
      setImage(URL.createObjectURL(selected));
      setFile(selected);
    }
  };

  const handleChange = (e) => {
    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      alert("Please upload or capture an image first.");
      return;
    }

    const token = localStorage.getItem("mughalsLoggedIn");

    const form = new FormData();
    form.append("image", file);
    form.append("name", formData.name);
    form.append("NIC", formData.cnic);
    form.append("registerDate", formData.registerDate);
    form.append("address", formData.address);

    licenses.forEach((license, index) => {
      form.append(`licenses[${index}][licenseNumber]`, license);
    });

    try {
      const response = await axios.post("/api/customers/add", form, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: `Bearer ${token}`,
        },
      });

      alert("Customer added successfully!");
      console.log("Response:", response.data);

      // Reset form
      setFormData({ name: "", cnic: "", registerDate: "", address: "" });
      setLicenses([]);
      setLicenseInput("");
      removeImage();
    } catch (error) {
      console.error("Error adding customer:", error);
      alert("Failed to add customer.");
    }
  };

  return (
    <div className="bg-light">
      {!showCamera && (
        <div className="p-4">
          <h2 className="text-start text-uppercase mb-4" style={{ color: "#9F33FF" }}>
            Add Customer
          </h2>

          <div className="row mb-4 gx-2 gy-2">
            <div className="col-12 col-md-6">
              <label className="w-100 btn text-white fs-5 d-flex align-items-center justify-content-center gap-2"
                     style={{ backgroundColor: "#9F33FF" }}>
                <FaUpload /> Upload Image
                <input type="file" accept="image/*" onChange={handleUpload} hidden />
              </label>
            </div>
            <div className="col-12 col-md-6">
              <button
                type="button"
                className="btn w-100 text-white fs-5 d-flex align-items-center justify-content-center gap-2"
                style={{ backgroundColor: "#9F33FF" }}
                onClick={() => setShowCamera(true)}
              >
                <FaCamera /> Capture Image
              </button>
            </div>
          </div>

          {image && (
            <div className="position-relative mb-4" style={{ maxWidth: "500px", margin: "auto" }}>
              <img
                src={image}
                alt="preview"
                className="img-fluid rounded border shadow"
                style={{ objectFit: "cover", aspectRatio: "4 / 3", width: "100%" }}
              />
              <button
                onClick={removeImage}
                className="btn position-absolute top-0 end-0 m-2 text-white"
                style={{ backgroundColor: "#9F33FF" }}
              >
                <FaTimes />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <input name="name" className="form-control p-3" placeholder="Full Name" value={formData.name} onChange={handleChange} required />
            </div>
            <div className="mb-3">
              <input name="cnic" className="form-control p-3" placeholder="CNIC Number" value={formData.cnic} onChange={handleChange} required />
            </div>
            <div className="mb-3">
              <input name="registerDate" type="date" className="form-control p-3" value={formData.registerDate} onChange={handleChange} required />
            </div>
            <div className="mb-3">
              <input name="address" className="form-control p-3" placeholder="Address" value={formData.address} onChange={handleChange} required />
            </div>

            <div className="mb-3 d-flex flex-column flex-md-row">
              <input
                type="text"
                className="form-control me-md-2 mb-2 mb-md-0 p-3"
                placeholder="Add License"
                value={licenseInput}
                onChange={(e) => setLicenseInput(e.target.value)}
              />
              <button
                type="button"
                className="btn text-white d-flex align-items-center justify-content-center gap-2 p-3"
                style={{ backgroundColor: "#9F33FF" }}
                onClick={() => {
                  if (licenses.length < 5 && licenseInput.trim() !== "") {
                    setLicenses([...licenses, licenseInput.trim()]);
                    setLicenseInput("");
                  }
                }}
              >
                <FaPlus /> Add
              </button>
            </div>

            <ul className="mb-3 list-unstyled">
              {licenses.map((lic, idx) => (
                <li key={idx} className="d-flex align-items-center justify-content-between mb-2 p-2 rounded bg-light border">
                  <span>{lic}</span>
                  <button
                    onClick={() => setLicenses(licenses.filter((_, i) => i !== idx))}
                    className="btn btn-sm text-white"
                    style={{ backgroundColor: "#9F33FF" }}
                    title="Remove License"
                  >
                    <FaTrash />
                  </button>
                </li>
              ))}
            </ul>

            <button
              type="submit"
              className="btn w-100 mt-2 text-white fs-5 d-flex align-items-center justify-content-center gap-2 p-3"
              style={{ backgroundColor: "#9F33FF" }}
            >
              <FaCheck /> Submit
            </button>
          </form>
        </div>
      )}

      {showCamera && (
        <div className="position-fixed top-0 start-0 w-100 h-100 d-flex flex-column justify-content-center align-items-center bg-dark"
             style={{ zIndex: 1050 }}>
          <video ref={videoRef}
                 className="w-100 h-100"
                 style={{ objectFit: "cover", maxHeight: "100vh", maxWidth: "100vw" }}
                 autoPlay playsInline />
          <canvas ref={canvasRef} style={{ display: "none" }} />
          <div className="d-flex justify-content-center gap-3 position-absolute" style={{ bottom: "20px" }}>
            <button className="btn text-white d-flex align-items-center gap-2"
                    style={{ backgroundColor: "#9F33FF" }}
                    onClick={captureImage}>
              <FaRegDotCircle /> Capture
            </button>
            <button className="btn text-white d-flex align-items-center gap-2"
                    style={{ backgroundColor: "#9F33FF" }}
                    onClick={() => setShowCamera(false)}>
              <FaTimesCircle /> Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}