import React, { useEffect, useState } from 'react';
import axios from '../Axios/Axios';
import Swal from 'sweetalert2';
import 'bootstrap/dist/css/bootstrap.min.css';

const History = () => {
  const [data, setData] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [customerFilter, setCustomerFilter] = useState('');
  const [dateFilter, setDateFilter] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const recordsPerPage = 5;

  const fetchData = async () => {
    const mughalsLoggedIn = localStorage.getItem("mughalsLoggedIn");
    try {
      const res = await axios.get('/api/assignmaterial/all', {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${mughalsLoggedIn}`,
        }
      });
      setData(res.data);
      setFilteredData(res.data);
    } catch (err) {
      console.error('Failed to fetch data:', err);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleDelete = async (id) => {
    Swal.fire({
      title: 'Are you sure?',
      text: 'This record will be deleted!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Yes, delete it!',
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          await axios.delete(`/api/history/${id}`);
          fetchData();
          Swal.fire('Deleted!', 'Record has been deleted.', 'success');
        } catch (err) {
          Swal.fire('Error!', 'Failed to delete record.', 'error');
        }
      }
    });
  };

  const handleFilter = () => {
    let filtered = data;

    if (customerFilter) {
      filtered = filtered.filter(item =>
        item.customerId?.name.toLowerCase().includes(customerFilter.toLowerCase())
      );
    }

    if (dateFilter) {
      filtered = filtered.filter(item =>
        new Date(item.assignedAt).toISOString().slice(0, 10) === dateFilter
      );
    }

    setFilteredData(filtered);
    setCurrentPage(1);
  };

  const indexOfLastRecord = currentPage * recordsPerPage;
  const indexOfFirstRecord = indexOfLastRecord - recordsPerPage;
  const currentRecords = filteredData.slice(indexOfFirstRecord, indexOfLastRecord);
  const totalPages = Math.ceil(filteredData.length / recordsPerPage);

  return (
    <div className=" mt-5">
      <h3 className="mb-4 text-dark">History Records</h3>

      <div className="row mb-4">
        <div className="col-md-4 mb-2">
          <input
            type="text"
            placeholder="Filter by Customer Name"
            className="form-control"
            value={customerFilter}
            onChange={(e) => setCustomerFilter(e.target.value)}
          />
        </div>
        <div className="col-md-4 mb-2">
          <input
            type="date"
            className="form-control"
            value={dateFilter}
            onChange={(e) => setDateFilter(e.target.value)}
          />
        </div>
        <div className="col-md-4 mb-2">
          <button className="btn border-0 bg-custom w-100" onClick={handleFilter}>
            Apply Filters
          </button>
        </div>
      </div>

      <div className="table-responsive rounded bg-white">
        <table className="w-100 table-custom table-striped table-hover text-center mb-0">
          <tbody>
            <tr className="text-white py-5 bg-custom custom-row">
              <td>#</td>
              <td>Customer Name</td>
              <td>NIC</td>
              <td>Material</td>
              <td>Quantity</td>
              <td>Date</td>
              <td>Actions</td>
            </tr>
            {currentRecords.length > 0 ? (
              currentRecords.map((record, index) => (
                <tr key={record._id} className="custom-row">
                  <td>{indexOfFirstRecord + index + 1}</td>
                  <td>{record.customerId?.name}</td>
                  <td>{record.customerNIC}</td>
                  <td>{record.materialId?.name}</td>
                  <td>{record.assignedQuantity}</td>
                  <td>{new Date(record.assignedAt).toLocaleDateString()}</td>
                  <td>
                    <button
                      className="btn border-0 bg-custom"
                      onClick={() => handleDelete(record._id)}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="7" className="text-muted">
                  No records found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>


      <div className="d-flex justify-content-between align-items-center mt-3">
        <button
          className="btn btn-outline-primary"
          onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
          disabled={currentPage === 1}
        >
          Previous
        </button>
        <span>Page {currentPage} of {totalPages}</span>
        <button
          className="btn btn-outline-primary"
          onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
          disabled={currentPage === totalPages}
        >
          Next
        </button>
      </div>
    </div>
  );
};

export default History;