import React, { useState, useEffect } from "react";
import axios from "../Axios/Axios";
import Swal from 'sweetalert2';
import jsPDF from 'jspdf';

const AssignMaterial = () => {
    const [customers, setCustomers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");

    const [selectedCustomer, setSelectedCustomer] = useState(null); // Now it's the whole object
    const [selectedLicense, setSelectedLicense] = useState('');
    const [selectedMaterial, setSelectedMaterial] = useState('');
    const [availableQty, setAvailableQty] = useState(0);
    const [assignQty, setAssignQty] = useState('');
    const [remainingQty, setRemainingQty] = useState(0);
    const [showModal, setShowModal] = useState(false);
    const [confirming, setConfirming] = useState(false);
    // const [materials] = useState([
    //     { name: 'Cement', quantity: 100 },
    //     { name: 'Steel', quantity: 50 },
    //     { name: 'Bricks', quantity: 1000 },
    // ]);

    const [materials, setMaterials] = useState([]);


    useEffect(() => {
        const mughalsLoggedIn = localStorage.getItem("mughalsLoggedIn");

        const fetchCustomers = async () => {
            try {
                setLoading(true);
                const res = await axios.get("/api/customers", {
                    headers: {
                        Authorization: `Bearer ${mughalsLoggedIn}`,
                    },
                });

                setCustomers(res.data); // data inside `data`
            } catch (err) {
                setError("Failed to fetch customer data.");
                console.error(err);
            } finally {
                setLoading(false);
            }
        };

        const fetchMaterials = async () => {
            try {
                const res = await axios.get("/api/materials/all", {
                    headers: {
                        Authorization: `Bearer ${mughalsLoggedIn}`,
                    },
                });
                console.log(res);
                setMaterials(res.data); // assumes array of materials
            } catch (err) {
                console.error("Error fetching materials:", err);
            }
        };

        fetchCustomers();
        fetchMaterials();
    }, []);


    useEffect(() => {
        const material = materials.find(mat => mat._id === selectedMaterial);
        if (material) {
            setAvailableQty(material.quantity);
            setRemainingQty(material.quantity - (parseInt(assignQty) || 0));
        } else {
            setAvailableQty(0);
            setRemainingQty(0);
        }
    }, [selectedMaterial, assignQty, materials]);


    // const handleAssign = async () => {
    //     if (!selectedCustomer || !selectedLicense || !selectedMaterial || !assignQty) {
    //         Swal.fire('Error', 'Please complete all fields!', 'error');
    //         return;
    //     }

    //     if (assignQty <= 0 || assignQty > availableQty) {
    //         Swal.fire('Error', 'Invalid assign quantity!', 'error');
    //         return;
    //     }

    //     const mughalsLoggedIn = localStorage.getItem("mughalsLoggedIn");

    //     try {
    //         const response = await axios.post("/api/assignmaterial/assign", {
    //             customerId: selectedCustomer._id,
    //             customerNIC: selectedCustomer.NIC,
    //             license: selectedLicense,
    //             materialId: selectedMaterial,
    //             assignedQuantity: assignQty,
    //         }, {
    //             headers: {
    //                 "Content-Type": "application/json",
    //                 Authorization: `Bearer ${mughalsLoggedIn}`,
    //             }
    //         });

    //         Swal.fire('Success!', `Assigned ${assignQty} items successfully!`, 'success');

    //         // Clear fields
    //         setAssignQty('');
    //         setSelectedMaterial('');
    //         setAvailableQty(0);
    //         setRemainingQty(0);
    //     } catch (err) {
    //         console.error("Assignment failed:", err);
    //         Swal.fire('Error', 'Failed to assign material.', 'error');
    //     }
    // };


    const handleAssign = () => {
        if (!selectedCustomer || !selectedLicense || !selectedMaterial || !assignQty) {
            Swal.fire('Error', 'Please complete all fields!', 'error');
            return;
        }

        if (assignQty <= 0 || assignQty > availableQty) {
            Swal.fire('Error', 'Invalid assign quantity!', 'error');
            return;
        }

        setShowModal(true); // Show modal instead of submitting
    };

    const handleConfirmAssign = async () => {
        const mughalsLoggedIn = localStorage.getItem("mughalsLoggedIn");

        try {
            const response = await axios.post("/api/assignmaterial/assign", {
                customerId: selectedCustomer._id,
                customerNIC: selectedCustomer.NIC,
                license: selectedLicense,
                materialId: selectedMaterial,
                assignedQuantity: assignQty,
            }, {
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${mughalsLoggedIn}`,
                }
            });

            Swal.fire('Success!', `Assigned ${assignQty} items successfully!`, 'success');

            // Generate PDF
            const doc = new jsPDF();
            doc.text("Material Assignment Details", 20, 20);
            doc.text(`Customer: ${selectedCustomer?.name}`, 20, 30);
            doc.text(`NIC: ${selectedCustomer?.NIC}`, 20, 40);
            doc.text(`License: ${selectedLicense}`, 20, 50);
            doc.text(`Material: ${materials.find(mat => mat._id === selectedMaterial)?.name}`, 20, 60);
            doc.text(`Assigned Quantity: ${assignQty}`, 20, 70);
            doc.save("material-assignment.pdf");

            // Don’t hide modal
            // Reset values
            setAssignQty('');
            setSelectedMaterial('');
            setAvailableQty(0);
            setRemainingQty(0);
        } catch (err) {
            console.error("Assignment failed:", err);
            Swal.fire('Error', 'Failed to assign material.', 'error');
        }
    };

    return (
        <div className="mt-4 p-4">
            <h4 className="mb-4">Give Materials</h4>

            <div className="mb-3">
                <label className="form-label text-dark">Select Customer</label>
                <select
                    className="form-select"
                    value={selectedCustomer?._id || ''}
                    onChange={e => {
                        const found = customers.find(c => c._id === e.target.value);
                        setSelectedCustomer(found || null);
                        setSelectedLicense('');
                    }}
                >
                    <option value="">-- Select --</option>
                    {customers?.map(cust => (
                        <option key={cust._id} value={cust._id}>{cust.name}</option>
                    ))}
                </select>
            </div>

            {selectedCustomer && (
                <>
                    <div className="mb-3">
                        <label className="form-label text-dark">NIC</label>
                        <input type="text" className="form-control" value={selectedCustomer.NIC} readOnly />
                    </div>

                    <div className="mb-3">
                        <label className="form-label text-dark">Select License</label>
                        <select
                            className="form-select"
                            value={selectedLicense}
                            onChange={e => setSelectedLicense(e.target.value)}
                        >
                            <option value="">-- Select License --</option>
                            {selectedCustomer.licenses?.map((license, i) => (
                                <option key={license._id} value={license._id}>
                                    {license.licenseNumber}
                                </option>
                            ))}
                        </select>
                    </div>
                </>
            )}

            {selectedLicense && (
                <>
                    <div className="mb-3">
                        <label className="form-label text-dark">Select Material</label>
                        <select
                            className="form-select"
                            value={selectedMaterial}
                            onChange={e => setSelectedMaterial(e.target.value)}
                        >
                            <option value="">-- Select Material --</option>
                            {materials?.map(mat => (
                                <option key={mat._id} value={mat._id}>{mat.name}</option>
                            ))}
                        </select>

                    </div>
                </>
            )}

            {selectedMaterial && (
                <>
                    <div className="mb-3">
                        <label className="form-label text-dark">Available Quantity</label>
                        <input type="number" className="form-control" value={availableQty} readOnly />
                    </div>

                    <div className="mb-3">
                        <label className="form-label text-dark">Give Quantity</label>
                        <input
                            type="number"
                            className="form-control"
                            value={assignQty}
                            onChange={e => {
                                const val = parseInt(e.target.value);
                                setAssignQty(val > 0 ? val : '');
                            }}
                        />
                    </div>

                    <div className="mb-3">
                        <label className="form-label text-dark">Remaining Quantity After Assignment</label>
                        <input type="number" className="form-control" value={remainingQty} readOnly />
                    </div>

                    <button
                        className="btn btn-lg border-0 text-white px-4"
                        style={{ backgroundColor: "#9F33FF" }}
                        onClick={() => setShowModal(true)}
                    >
                        Give Material
                    </button>



                    {showModal && (
                        <div className="modal fade show d-block" tabIndex="-1" role="dialog" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>
                            <div className="modal-dialog" role="document">
                                <div className="modal-content">
                                    <div className="modal-header">
                                        <h5 className="modal-title">Confirm Assignment</h5>
                                        <button type="button" className="btn-close" onClick={() => setShowModal(false)}></button>
                                    </div>
                                    <div className="modal-body">
                                        <p><strong>Customer:</strong> {selectedCustomer?.name}</p>
                                        <p><strong>NIC:</strong> {selectedCustomer?.NIC}</p>
                                        <p><strong>License:</strong> {selectedCustomer?.licenses?.find(l => l._id === selectedLicense)?.licenseNumber}</p>
                                        <p><strong>Material:</strong> {materials?.find(m => m._id === selectedMaterial)?.name}</p>
                                        <p><strong>Assign Quantity:</strong> {assignQty}</p>
                                    </div>
                                    <div className="modal-footer">
                                        <button
                                            className="btn btn-secondary"
                                            onClick={() => setShowModal(false)}
                                            disabled={confirming}
                                        >
                                            Close
                                        </button>
                                        <button
                                            className="btn px-5 text-white border-0"
                                            style={{ backgroundColor: "#9F33FF" }}
                                            onClick={async () => {
                                                setConfirming(true);
                                                try {
                                                    await handleAssign(); // Call existing API logic

                                                    // ✅ jsPDF logic here
                                                    const { jsPDF } = await import("jspdf");

                                                    // Create a new document
                                                    const doc = new jsPDF();

                                                    // Set margins
                                                    const marginLeft = 20;
                                                    let verticalPosition = 20;

                                                    // Company Name (centered)
                                                    doc.setFontSize(18);
                                                    doc.setFont("helvetica", "bold");
                                                    doc.text("Mughal Explosives", doc.internal.pageSize.getWidth() / 2, verticalPosition, { align: "center" });

                                                    verticalPosition += 10;
                                                    doc.setFontSize(12);
                                                    doc.setFont("helvetica", "normal");
                                                    doc.text("Material Assignment Slip", doc.internal.pageSize.getWidth() / 2, verticalPosition, { align: "center" });

                                                    // Add Date
                                                    verticalPosition += 10;
                                                    const today = new Date();
                                                    const formattedDate = today.toLocaleDateString();
                                                    doc.text(`Date: ${formattedDate}`, marginLeft, verticalPosition);

                                                    verticalPosition += 15;

                                                    // Draw a box
                                                    doc.setDrawColor(0);
                                                    doc.setLineWidth(0.5);
                                                    doc.rect(marginLeft - 5, verticalPosition - 10, 170, 70);

                                                    // Customer Info
                                                    doc.setFont("helvetica", "bold");
                                                    doc.text("Customer Information:", marginLeft, verticalPosition);
                                                    verticalPosition += 8;
                                                    doc.setFont("helvetica", "normal");
                                                    doc.text(`Name: ${selectedCustomer.name}`, marginLeft, verticalPosition);
                                                    verticalPosition += 7;
                                                    doc.text(`NIC: ${selectedCustomer.NIC}`, marginLeft, verticalPosition);
                                                    verticalPosition += 7;
                                                    doc.text(`License #: ${selectedCustomer.licenses?.find(l => l._id === selectedLicense)?.licenseNumber}`, marginLeft, verticalPosition);

                                                    verticalPosition += 15;

                                                    // Material Info Box
                                                    doc.setDrawColor(0);
                                                    doc.setLineWidth(0.5);
                                                    doc.rect(marginLeft - 5, verticalPosition - 10, 170, 40);

                                                    doc.setFont("helvetica", "bold");
                                                    doc.text("Material Information:", marginLeft, verticalPosition);
                                                    verticalPosition += 8;

                                                    doc.setFont("helvetica", "normal");
                                                    doc.text(`Material Name: ${materials?.find(m => m._id === selectedMaterial)?.name}`, marginLeft, verticalPosition);
                                                    verticalPosition += 7;
                                                    doc.text(`Assigned Quantity: ${assignQty}`, marginLeft, verticalPosition);

                                                    verticalPosition += 20;

                                                    // Footer
                                                    doc.setFont("helvetica", "italic");
                                                    doc.setFontSize(10);
                                                    doc.text("This document is generated by Mughal Explosives Management System.", marginLeft, 280);

                                                    // Save PDF
                                                    doc.save(`Material_Assignment_${selectedCustomer.name}_${formattedDate}.pdf`);

                                                } catch (error) {
                                                    console.error(error);
                                                } finally {
                                                    setConfirming(false);
                                                }
                                            }}
                                            disabled={confirming}
                                        >
                                            {confirming ? 'Please wait...' : 'Confirm'}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}


                </>
            )}
        </div>
    );
};

export default AssignMaterial;